            identities += await self.pipe.zrangebyscore(self.key('parents'),1,'+inf')
        else:
            raise ValueError(kind)
        if not identities:
            return []
        identities = list(dict.fromkeys(identities))
        raws = await self.pipe.hmget(self.key('jobs'),identities)

