  }
  if (!python) command('npm', ['run', 'build'], { stdio: 'inherit' });
  const redis = await start("redis", "redis:7-alpine", 6379);
  const postgres = redisOnly ? undefined : await start("postgres", "postgres:16-alpine", 5432, [
