    return {
      ready: true,
      matchedPattern: pattern.source,
      ...(extractUrl(line) ?? match[1] ? { resolvedUrl: extractUrl(line) ?? match[1] } : {}),
    };
  }

  return {
    ready: false,
  };
}

function extractUrl(line: string): string | undefined {
  const match = line.match(/https?:\/\/[^\s]+/i);
  return match?.[0];
}

