it('keeps transient form state through a flow and links a real trace from its report', async()=>{
  const root=await mkdtemp(path.join(os.tmpdir(),'probefn-live-flow-'));
  const app=createServer((_req,res)=>{res.setHeader('Content-Type','text/html');res.end(`<html><body><input id="name"><button id="submit" onclick="document.querySelector('#result').textContent=document.querySelector('#name').value+':'+(++window.count)">Submit</button><p id="result">Waiting</p><script>window.count=0</script></body></html>`);});
  await new Promise<void>(resolve=>app.listen(0,'127.0.0.1',resolve));
  const url=`http://127.0.0.1:${(app.address() as {port:number}).port}`;
  const runtime=new ProbefnRuntime(root);
  try {
    await writeFile(path.join(root,'config.mjs'),`export default ${JSON.stringify({projectName:'flow',devServers:{web:{mode:'attach',name:'web',url}},deterministicDefaults:{networkIdleMs:10}})}`);
    await startSessionFromConfig(runtime,{configPath:'config.mjs',sessionId:'flow',runId:'flow'});
    await writeFile(path.join(root,'flow.json'),JSON.stringify({version:1,steps:[{command:'page.open',url},{command:'page.act',action:'fill',selector:'#name',value:'Ada'},{command:'page.act',action:'click',selector:'#submit'},{command:'checkpoint.create',name:'after',includeTrace:true},{command:'report.export',format:'json'}]}));
    const result=await runFlow(runtime,{sessionId:'flow',file:'flow.json'});
    expect(result.ok).toBe(true);
    const dom=JSON.parse(await readFile(path.join(root,'.artifacts/runs/flow/checkpoints/after/dom.json'),'utf8'));
    expect.soft(dom.html).toContain('<p id="result">Ada:1</p>');
    const report=JSON.parse(await readFile(path.join(root,'.artifacts/runs/flow/report.json'),'utf8'));
    expect(report.tracePath).toBeTypeOf('string');
    expect((await readFile(path.join(root,report.tracePath))).subarray(0,2).toString()).toBe('PK');
  } finally {
    await stopSession(runtime,'flow').catch(()=>undefined);
    app.closeAllConnections();await new Promise<void>(resolve=>app.close(()=>resolve()));
    await rm(root,{recursive:true,force:true});
  }
});
