): Promise<CliCommandResult> {
  if (args[0] !== 'flow') {
    throw createProbefnError({
      code: 'E_CONFIG_INVALID',
      message: `Unknown run subcommand ${args[0] ?? '<none>'}.`,
      retryable: false,
