  async join(meetingUrl: string, config: BotConfig): Promise<void> {
    await this.sdk.init(this.sdkConfig);
    this.botId = (config as InternalBotConfig).__botId ?? this.botId;
    this.participantTracker.setBotId(this.botId);
    this.joinedAt = new Date().toISOString();
    this.endedAt = undefined;

    const { meetingNumber, password } = parseMeetingUrl(meetingUrl);
    const displayName = config.displayName ?? 'RecFn Bot';

    await this.sdk.join({
      meetingNumber,
      password,
      displayName,
    });

    this.connected = true;
    this.sdk.startRawAudio();
    this.sdk.startRawVideo();
  }

  async leave(): Promise<void> {
    this.sdk.stopRawAudio();
    this.sdk.stopRawVideo();
    await this.sdk.leave();
    this.connected = false;
    this.endedAt = this.endedAt ?? new Date().toISOString();
  }

  getAudioStream(): ReadableStream<AudioChunk> {
    return createAudioStream(this.sdk);
  }

  getVideoStream(): ReadableStream<VideoChunk> {
    return createVideoStream(this.sdk);
  }

  async getParticipants(): Promise<Participant[]> {
    const tracked = this.participantTracker.getAll();
    if (tracked.length > 0) {
      return tracked;
    }
    return snapshotParticipants(this.sdk, this.botId);
  }

  }

  async join(meetingUrl: string, botConfig: BotConfig): Promise<void> {
    const joinTimeout =
      this.config.joinTimeout ?? botConfig.joinTimeout ?? 30_000;
    this.botId = (botConfig as InternalBotConfig).__botId ?? this.botId;

    this.session = await createManagedBrowserSession(
      this.config,
      meetingUrl,
      joinTimeout,
      this.hooks.createSession,
    );

    await this.hooks.joinMeeting(this.session.page, joinTimeout, botConfig);

    this.connected = true;
    this.participantTracker = this.hooks.createParticipantTracker(
      this.session.page,
      this.botId,
    );
    this.participantTracker.setBotId?.(this.botId);
    this.chatTracker = this.hooks.createChatTracker(this.session.page);

    for (const cb of this.participantJoinCallbacks) {
      this.participantTracker.onJoin(cb);
    }
    for (const cb of this.participantLeaveCallbacks) {
      this.participantTracker.onLeave(cb);
    }
    for (const cb of this.chatMessageCallbacks) {
      this.chatTracker.onMessage(cb);
    }

    await this.participantTracker.startObserving();
    await this.chatTracker.startObserving();
  }

  async leave(): Promise<void> {
    this.participantTracker?.stopObserving();
