### Bot worker

```ts
import { createBotWorker, MemoryQueueAdapter, QUEUE_NAMES } from '@recfn/server';

const worker = createBotWorker({
  store,
  queue,
  logger,
  platformAdapters: new Map([['zoom', zoomAdapter]]),
