else{const worker=createBotWorker({environment:'test',store,queue:new MemoryQueueAdapter(),logger:new MemoryLogger(),recoveryNamespaces:['native-pg'],platformAdapterFactories:new Map([['zoom',()=>({async join(){appendFileSync(${JSON.stringify(calls)},'join\\n');console.log('provider-started');${mode === 'hang' ? 'await new Promise(()=>{});' : "throw new Error('remote accepted, ACK lost');"}},async leave(){}})]])});receipt={processed:await worker.processNext()};await worker.cancelCaptures();}
