  await assert.rejects(parent.store.createBot(input), error => error.code === 'RATE_LIMIT_EXCEEDED');
  await parent.close();
  result = { postgres: version, adapter: 'shared Kysely/PostgreSQL', independentChildren: children.length, admissionWinners: 1, providerCallsPerBot: 1, heldCapacityReopen: true, atomicCompletionRollback: true, killedOwnerNoTakeover: true };
