      const store = createMemoryStore();
      const { validateBotConfig } = await import('@recfn/core');
      const bot = await store.createBot({ namespace: 'cleanup', platform: 'zoom', meetingUrl: 'https://zoom.us/j/123', config: validateBotConfig({}) });
