import type { PlatformAdapter } from '@recfn/core';
import type { Logger } from '../integrations/logfn.js';

/**
 * Sends the consent message via the platform adapter's sendChatMessage.
 * Bot MUST NOT transition to recording until this completes (or fails non-fatally).
 * On failure: logs warning and returns (non-fatal — bot proceeds to recording).
 */
export async function sendConsentMessage(
  adapter: PlatformAdapter,
  message: string,
  botId: string,
  logger: Logger,
): Promise<void> {
  try {
    await adapter.sendChatMessage(message);
    logger.info('bot.consent_sent', { botId, message });
  } catch {
    logger.warn('bot.consent_failed', { botId });
    // Non-fatal: proceed to recording per TV-BOT-010
  }
}
  }

  onChatMessage(cb: (message: ChatMessage) => void): void {
    this.chatMessageCallbacks.push(cb);
    this.chatTracker?.onMessage(cb);
  }

  async sendChatMessage(text: string): Promise<void> {
    await this.chatTracker?.send(text);
  }

  async getMetadata(): Promise<MeetingMetadata> {
    let title = this.hooks.defaultTitle;
    if (this.session) {
      try {
        title = (await this.session.page.title()) ?? title;
      } catch {
        // Ignore: title access is best effort.
      }
    }

      observerActive = true;

      try {
        const poll = async () => {
          if (!observerActive) {
            return;
          }

          const entries = await options.page.evaluate(options.evaluateMessages);
          for (const entry of entries) {
            if (!entry.text) {
              continue;
            }

            const message: ChatMessage = {
              participantId: entry.participantId,
              text: entry.text,
              timestamp: entry.timestamp ?? new Date().toISOString(),
            };
            const exists = messages.some(
              (current) =>
                current.participantId === message.participantId &&
                current.text === message.text,
            );
            if (exists) {
              continue;
            }

            messages.push(message);
            for (const cb of messageCallbacks) {
              cb(message);
            }
          }
        };

        await poll();
        const interval = setInterval(poll, pollIntervalMs);
        stopPolling = () => clearInterval(interval);
      } catch {
        // Non-fatal: browser DOM polling is best effort.
      }
    },

    stopObserving(): void {
      observerActive = false;
      stopPolling?.();
      stopPolling = undefined;
    },
  };
}
  onChatMessage(cb: (msg: ChatMessage) => void): void {
    this.chatTracker.onMessage(cb);
  }

  async sendChatMessage(text: string): Promise<void> {
    await this.chatTracker.send(text);
  }

  async getMetadata(): Promise<MeetingMetadata> {
    const info = this.sdk.getMeetingInfo();
    return {
      id: info.meetingNumber,
      botId: this.botId,
      title: info.meetingTopic,
      startTime: this.joinedAt,


    // Successfully joined
    await transitionBot(lifecycleDeps, botId, namespace, 'joined');
    await persistMetadataSnapshot(bot, adapter, 'joined');

    if (closing || owner.cancelled) { await failOwner(owner, 'Worker stopped after join.'); return; }
    if (process.env.RECFN_POC_JOIN_ONLY === '1') {
      logger.info('bot.join_only.active', { botId, namespace });
      activeSessions.set(botId, {
        botId,
        namespace,
        adapter,
        capturePromise: Promise.resolve({
          data: new Uint8Array(),
          format: 'wav',
          duration: 0,
          size: 0,
        }),
        recordingRequired: false,
      });
      setupParticipantMonitoring(bot, adapter);
      setupChatMessagePersistence(bot, adapter, 'joined');
      return;
    }

    // Send consent message before recording (BOT-008, SEC-006)
    const consentMsg =
      bot.config.consentMessage ?? 'This meeting is being recorded';
    await sendConsentMessage(adapter, consentMsg, botId, logger);

    // Transition to recording (only after consent message sent)
    await transitionBot(lifecycleDeps, botId, namespace, 'recording');
    await persistMetadataSnapshot(bot, adapter, 'recording');
